import{f as t,o as n,c as i,aq as r}from"./chunks/framework.CAfuRaXs.js";const g=JSON.parse('{"title":"Backendtestkonzept","description":"","frontmatter":{},"headers":[],"relativePath":"technik/testconcepts/backend.md","filePath":"technik/testconcepts/backend.md"}'),s={name:"technik/testconcepts/backend.md"};function a(d,e,u,o,c,l){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="backendtestkonzept" tabindex="-1">Backendtestkonzept <a class="header-anchor" href="#backendtestkonzept" aria-label="Permalink to &quot;Backendtestkonzept&quot;">​</a></h1><h2 id="automatisierte-teststufen" tabindex="-1">Automatisierte Teststufen <a class="header-anchor" href="#automatisierte-teststufen" aria-label="Permalink to &quot;Automatisierte Teststufen&quot;">​</a></h2><p>Die folgenden Teststufen werden durch die Workflows automatisiert durchlaufen. Bevor ein Pull-Requests gemergt wird, müssen alle Teststufen erfolgreich durchlaufen sein.</p><p>Die Tests werden mittels JUnit5 und AssertJ geschrieben.</p><p>Die <a href="#architekturtests">Architekturtests</a> sind die einzigen Tests, die bei einer Implementierung eines Features nicht aktualisiert werden.</p><h3 id="unittests" tabindex="-1">Unittests <a class="header-anchor" href="#unittests" aria-label="Permalink to &quot;Unittests&quot;">​</a></h3><p>Ziel: Sicherstellen der fachlichen Funktionalität einer Klasse.</p><p>Was: Neue oder geänderte Funktionalität einer Klasse.</p><p>Wie: Erstellen, Anpassen oder Erweitern vorhandener Testsuits. Es sollte bei eigenen Klassen eine Codecoverage von 100% (Methoden und Lines) erreicht werden. Komponenten, auf die die Testunit zugreifen, werden gemockt.</p><p>Verantwortung: Entwickler*in, der/die die Änderung implementiert hat.</p><h3 id="integrationstests-zur-authentifizierung" tabindex="-1">Integrationstests zur Authentifizierung <a class="header-anchor" href="#integrationstests-zur-authentifizierung" aria-label="Permalink to &quot;Integrationstests zur Authentifizierung&quot;">​</a></h3><p>Ziel: Sicherstellen, dass der Zugriff auf Endpunkte der Services mit der erforderlichen <a href="./../systemspecification/backend.html#authentifizierung">Authentifizierung</a> erfolgt.</p><p>Was: Geänderte Authentifizierungsregeln, neue oder geänderte Endpunkte eines Services.</p><p>Wie: Durch Anpassung der <code>configuration.SecurityConfigurationTest</code>-Testsuit. Das Verhalten mit und ohne korrekter Authentifizierung ist zu prüfen. Die korrekte Fachlichkeit des Zugriffes soll dabei nicht geprüft werden.</p><p>Verantwortung: Entwickler*in, der/die die Änderung implementiert hat.</p><h3 id="integrationstests-zur-autorisierung" tabindex="-1">Integrationstests zur Autorisierung <a class="header-anchor" href="#integrationstests-zur-autorisierung" aria-label="Permalink to &quot;Integrationstests zur Autorisierung&quot;">​</a></h3><p>Ziel: Sicherstellen, dass der Zugriff auf die Operationen eines Services oder Repositories nur mit den erforderlichen <a href="./../systemspecification/backend.html#autorisierung">Berechtigungen</a> erfolgt.</p><p>Was:</p><ul><li>Neue oder geänderte Berechtigungen, von Methoden bei Services oder Repositories.</li><li>Neue oder geänderte Berechtigungen, aufgrund von neuen oder geänderten Abhängigkeiten.</li></ul><p>Wie: Durch Anpassungen in <code>service.&lt;Domain&gt;SecurityTest</code>. Der erfolgreiche Zugriff, sowie die Zugriffsverweigerung sind zu prüfen. Gibt es mehrere erforderliche Berechtigungen, müssen alle Kombinationen geprüft werden. Die korrekte logische Verknüpfung der Berechtigungen muss dabei beachtet werden. Die korrekte Fachlichkeit des Zugriffes soll dabei nicht geprüft werden.</p><p>Verantwortung: Entwickler*in, der/die die Änderung implementiert hat.</p><h3 id="integrationstest-des-microservices-unter-beachtung-der-fachlichkeit" tabindex="-1">Integrationstest des Microservices unter Beachtung der Fachlichkeit <a class="header-anchor" href="#integrationstest-des-microservices-unter-beachtung-der-fachlichkeit" aria-label="Permalink to &quot;Integrationstest des Microservices unter Beachtung der Fachlichkeit&quot;">​</a></h3><p>Ziel: Sicherstellen, dass die grundlegenden Einsatzmöglichkeiten eines Microservices gewährleistet sind, in dem die Komponenten des Microservices korrekt zusammenarbeiten.</p><p>Was: Stellvertretende positive wie negative Testfälle einer fachlichen Anforderung eines Services. Überprüfung des korrekten Umgangs mit Exceptions.</p><p>Wie: Durch Anpassungen in <code>rest.&lt;Domain&gt;ControllerIntegrationTest</code>, welche Zugriff auf die Endpunkte unter Verwendung der jeweiligen Authentifizierung durchführen. Eine vollständige Abdeckung aller fachlichen Szenarien ist nicht erforderlich, weil dies durch die <a href="#unittests">Unittests</a> der Services sichergestellt wird.</p><p>Verantwortung: Entwickler*in, der/die die elementare Änderung an der Fachlichkeit implementiert hat.</p><h3 id="architekturtests" tabindex="-1">Architekturtests <a class="header-anchor" href="#architekturtests" aria-label="Permalink to &quot;Architekturtests&quot;">​</a></h3><p>Ziel: Sicherstellen, dass formalisierte Regeln der Architektur eingehalten wurden.</p><p>Was: Die Regeln, die für den Service als relevant definiert wurden.</p><p>Wie: Durch Anpassungen in <code>ArchUnitTest</code>, unter Verwendung von Regeln aus <code>wls-common</code> und speziell für den Service erstellte Regeln. Bei der Implementierung von Anforderungen sind in der Regel keine Anpassungen an den Architekturtests vorzunehmen. Mit den Architekturtests wird aber sichergestellt, dass die Implementierung sich an die definierten Regeln hält.</p><p>Verantwortung: Entwickler*in, der/die das entsprechende Issue zur Pflege der Architekturtests umsetzt, oder bei Änderungen an der Architektur.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Serviceunabhängige Regeln werden im Modul <code>wls-common:testing</code> gepflegt. Gruppiert nach dem Testgegenstand der Regel, gibt es im Package <code>archunit.rule</code> Klassen mit Konstanten zu Regeln für Klassen und Methoden.</p></div>',32)])])}const p=t(s,[["render",a]]);export{g as __pageData,p as default};
